using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text.Json;

namespace DailyDiaryCard;

public static class SetupTests
{
    public static int Run(string root)
    {
        root=Path.GetFullPath(root);Directory.CreateDirectory(root);int index=0,failures=0;var results=new List<object>();
        string Fixture(){var path=Path.Combine(root,(++index).ToString("00"));Directory.CreateDirectory(path);return path;}
        void Check(bool ok){if(!ok)throw new Exception("断言失败");}
        void Test(string name,Action action){try{action();results.Add(new{name,passed=true});}catch(Exception e){failures++;results.Add(new{name,passed=false,error=e.ToString()});}}
        void Reject(Action action){bool rejected=false;try{action();}catch(Exception e) when(e is IOException or UnauthorizedAccessException or JsonException or ArgumentException){rejected=true;}Check(rejected);}
        string Config(string install)=>Path.Combine(install,"diary-card.json");
        VaultPlan New(string install)=>SetupService.Plan(Config(install),true,"","",true,"日记","YYYY/MM/YYYY-MM-DD");
        Test("未选择已有库地址时拒绝，不默用程序目录",()=>{var install=Fixture();Reject(()=>SetupService.Plan(Config(install),false,"","",true,"日记","YYYY/MM/YYYY-MM-DD"));Check(!File.Exists(Config(install))&&!Directory.Exists(Path.Combine(install,"data")));});
        Test("创建前预览内置模板与路径不写文件",()=>{var install=Fixture();var plan=New(install);Check(!Directory.Exists(plan.Config.VaultPath)&&!Directory.Exists(plan.Config.UserDataPath)&&!File.Exists(Config(install)));Check(plan.TemplateText==DefaultAssets.Template&&plan.Config.PathFor(new(2026,10,26)).EndsWith(Path.Combine("日记","2026","10","2026-10-26.md")));});
        Test("无仓库时在程序目录创建DailyNote并保存配置",()=>{var install=Fixture();var c=SetupService.Complete(New(install));Check(c.VaultPath==Path.Combine(install,"DailyNote")&&Directory.Exists(Path.Combine(c.VaultPath,".obsidian")));Check(DiarySession.ReadText(c.TemplatePath)==DefaultAssets.Template&&c.SetupVersion==2);Check(!File.Exists(c.PathFor(DateOnly.FromDateTime(DateTime.Now))));});
        Test("新库首次填写生成日记并持续更新同一文件",()=>{var c=SetupService.Complete(New(Fixture()));var day=new DateOnly(2026,10,26);var s=new DiarySession(c,day);var first=s.Template[0].Title;s.Edit(first,s.Bodies[first]+"新库中文\n");s.Save();s.Edit(first,s.Bodies[first]+"持续更新\n");s.Save();Check(Directory.GetFiles(c.DiaryFolder,"*.md",SearchOption.AllDirectories).Length==1&&DiarySession.ReadText(s.Target).Contains("持续更新")&&!DiarySession.ReadText(s.Target).Contains("{{date:"));});
        Test("内置背景以内容散列复制，设置引用正确",()=>{var c=SetupService.Complete(New(Fixture()));var p=Preferences.Load(c.UserDataPath);Check(p.BackgroundImage==DefaultAssets.BackgroundName&&File.ReadAllBytes(LocalBackground.Resolve(c.UserDataPath,p.BackgroundImage)).SequenceEqual(DefaultAssets.Read("background.jpg")));});
        Test("已有库沿用模板、记录目录与命名并保持原属性文件",()=>{var install=Fixture();var vault=MakeVault(install,"vault");var settings=Path.Combine(vault,".obsidian","daily-notes.json");var before=File.ReadAllBytes(settings);var detected=SetupService.Inspect(vault);var c=SetupService.Complete(SetupService.Plan(Config(install),false,vault,detected.Template,false,detected.Folder,detected.Format));Check(c.DiaryFolder==Path.Combine(vault,"records")&&c.DateFormat=="YYYY-MM-DD"&&new MarkdownDoc(DiarySession.ReadText(c.TemplatePath)).Sections.Count==2&&File.ReadAllBytes(settings).SequenceEqual(before));});
        Test("已有当天笔记和未知YAML在设置时逐字保留",()=>{var install=Fixture();var vault=MakeVault(install,"vault");var target=Path.Combine(vault,"records",DateTime.Now.ToString("yyyy-MM-dd")+".md");Directory.CreateDirectory(Path.GetDirectoryName(target)!);const string text="---\ncustom: 原属性\n---\n## 今天\n已有记录\n## 明天\n原任务\n## 额外\n其他内容\n";File.WriteAllText(target,text);SetupService.Complete(SetupService.Plan(Config(install),false,vault,"templates/custom.md",false,"records","YYYY-MM-DD"));Check(DiarySession.ReadText(target)==text);});
        Test("已有库缺少模板设置时使用内置模板且不改库设置",()=>{var install=Fixture();var vault=Path.Combine(install,"external");Directory.CreateDirectory(vault);File.WriteAllText(Path.Combine(vault,"原文.md"),"保留原文");var c=SetupService.Complete(SetupService.Plan(Config(install),false,vault,"",true,"日记","YYYY/MM/YYYY-MM-DD"));Check(c.UseBundledTemplate&&c.TemplatePath==DefaultAssets.TemplatePath(c.UserDataPath)&&Directory.GetFiles(vault).Length==1&&!Directory.Exists(Path.Combine(vault,".obsidian")));});
        Test("Periodic Notes日记配置可识别",()=>{var install=Fixture();var vault=Path.Combine(install,"vault");var dir=Path.Combine(vault,".obsidian","plugins","periodic-notes");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"data.json"),"{\"daily\":{\"folder\":\"daily\",\"format\":\"YYYY-MM-DD\",\"template\":\"templates/daily\"}}");var p=SetupService.Inspect(vault);Check(p.HasTemplate&&p.Template=="templates/daily.md"&&p.Folder=="daily"&&p.Source.Contains("Periodic"));});
        Test("已配置模板丢失时拒绝，不静默替换",()=>{var install=Fixture();var vault=MakeVault(install,"vault");Reject(()=>SetupService.Plan(Config(install),false,vault,"templates/missing.md",false,"records","YYYY-MM-DD"));Check(!File.Exists(Config(install)));});
        Test("没有二级标题和重复标题的模板均拒绝",()=>{var install=Fixture();var vault=MakeVault(install,"vault");var template=Path.Combine(vault,"templates","custom.md");File.WriteAllText(template,"# 一级\n正文");Reject(()=>SetupService.Plan(Config(install),false,vault,template,false,"records","YYYY-MM-DD"));File.WriteAllText(template,"## 重复\n甲\n## 重复\n乙");Reject(()=>SetupService.Plan(Config(install),false,vault,template,false,"records","YYYY-MM-DD"));});
        Test("不支持的命名规则拒绝，不改原配置",()=>{var install=Fixture();var c=SetupService.Complete(New(install));var original=File.ReadAllBytes(c.ConfigPath);Reject(()=>SetupService.Plan(c.ConfigPath,false,c.VaultPath,c.TemplatePath,false,"日记","YYYY-MM-DD dddd",c.UserDataPath));Check(File.ReadAllBytes(c.ConfigPath).SequenceEqual(original));});
        Test("DailyNote已有内容时拒绝新建以防覆盖",()=>{var install=Fixture();Directory.CreateDirectory(Path.Combine(install,"DailyNote"));var note=Path.Combine(install,"DailyNote","保留.md");File.WriteAllText(note,"不得覆盖");Reject(()=>SetupService.Complete(New(install)));Check(DiarySession.ReadText(note)=="不得覆盖"&&!File.Exists(Config(install)));});
        Test("配置提交失败时回滚本次创建的库及资源",()=>{var install=Fixture();Directory.CreateDirectory(Config(install));Reject(()=>SetupService.Complete(New(install)));Check(!Directory.Exists(Path.Combine(install,"DailyNote"))&&!Directory.Exists(Path.Combine(install,"data"))&&Directory.Exists(Config(install)));});
        Test("只读配置保存失败时旧配置保留且新库回滚",()=>{var install=Fixture();var vault=MakeVault(install,"original");var c=SetupService.Complete(SetupService.Plan(Config(install),false,vault,"templates/custom.md",false,"records","YYYY-MM-DD"));var original=File.ReadAllBytes(c.ConfigPath);File.SetAttributes(c.ConfigPath,FileAttributes.ReadOnly);try{Reject(()=>SetupService.Complete(New(install)));Check(File.ReadAllBytes(c.ConfigPath).SequenceEqual(original)&&!Directory.Exists(Path.Combine(install,"DailyNote")));}finally{File.SetAttributes(c.ConfigPath,FileAttributes.Normal);}});
        Test("切换仓库保留已有外观和背景偏好",()=>{var install=Fixture();var c=SetupService.Complete(New(install));var prefs=Path.Combine(c.UserDataPath,"settings.json");const string custom="{\"Theme\":\"night\",\"BackgroundImage\":\"my-image.jpg\",\"SectionTransparency\":0.6}";File.WriteAllText(prefs,custom);var vault=MakeVault(install,"second");var p=SetupService.Plan(c.ConfigPath,false,vault,"templates/custom.md",false,"records","YYYY-MM-DD",c.UserDataPath);SetupService.Complete(p);Check(DiarySession.ReadText(prefs)==custom&&Directory.Exists(c.VaultPath));});
        Test("便携新库随程序目录移动后仍可定位",()=>{var install=Fixture();var c=SetupService.Complete(New(install));string destination=install+"-moved";Check(SetupService.IsUnder(root,install)&&SetupService.IsUnder(root,destination));Directory.Move(install,destination);var loaded=CardConfig.Load(Path.Combine(destination,"diary-card.json"));Check(loaded.VaultPath==Path.Combine(destination,"DailyNote")&&loaded.UserDataPath==Path.Combine(destination,"data")&&File.Exists(loaded.TemplatePath));});
        Test("损坏的Obsidian设置可由明确手动配置修复程序寻址",()=>{var install=Fixture();var vault=MakeVault(install,"vault");File.WriteAllText(Path.Combine(vault,".obsidian","daily-notes.json"),"{ invalid");Reject(()=>SetupService.Inspect(vault));var c=SetupService.Complete(SetupService.Plan(Config(install),false,vault,"templates/custom.md",false,"records","YYYY-MM-DD"));Check(CardConfig.Load(c.ConfigPath).TemplatePath==c.TemplatePath);});
        Test("事务取消不会保留新库和默认资源",()=>{var install=Fixture();using(var transaction=SetupService.Prepare(New(install))){Check(Directory.Exists(transaction.Config.VaultPath));}Check(!Directory.Exists(Path.Combine(install,"DailyNote"))&&!File.Exists(Config(install)));});
        Test("Obsidian空日记目录使用仓库根目录及默认命名",()=>{var install=Fixture();var vault=MakeVault(install,"vault");File.WriteAllText(Path.Combine(vault,".obsidian","daily-notes.json"),"{\"folder\":\"\",\"format\":\"\",\"template\":\"templates/custom\"}");var p=SetupService.Inspect(vault);var c=SetupService.Complete(SetupService.Plan(Config(install),false,vault,p.Template,false,p.Folder,p.Format));Check(c.DiaryFolder==vault&&c.DateFormat=="YYYY-MM-DD");});
        Test("UTF8 BOM的Obsidian日记设置正常识别",()=>{var install=Fixture();var vault=MakeVault(install,"vault");File.WriteAllText(Path.Combine(vault,".obsidian","daily-notes.json"),"{\"folder\":\"records\",\"template\":\"templates/custom\"}",new System.Text.UTF8Encoding(true));var p=SetupService.Inspect(vault);Check(p.Template=="templates/custom.md"&&p.Folder=="records");});
        Test("已被其他卡片占用的日记库可以在提交前检测",()=>{var c=SetupService.Complete(New(Fixture()));using(var mutex=new System.Threading.Mutex(true,"Local\\DailyDiaryCard-"+VaultUse.Key(c),out bool first)){Check(first&&VaultUse.InUse(c));mutex.ReleaseMutex();}Check(!VaultUse.InUse(c));});
        DiarySession.AtomicText(Path.Combine(root,"setup-result.json"),JsonSerializer.Serialize(new{passed=results.Count-failures,failed=failures,results},CardConfig.Json));return failures==0?0:1;
    }
    public static string MakeVault(string root,string name)
    {
        var vault=Path.Combine(root,name);Directory.CreateDirectory(Path.Combine(vault,".obsidian"));Directory.CreateDirectory(Path.Combine(vault,"templates"));File.WriteAllText(Path.Combine(vault,".obsidian","daily-notes.json"),"{\"folder\":\"records\",\"format\":\"YYYY-MM-DD\",\"template\":\"templates/custom\",\"custom\":\"保留\"}");File.WriteAllText(Path.Combine(vault,"templates","custom.md"),"---\nkind: diary\ndate: \"{{date:YYYY-MM-DD}}\"\n---\n## 今天\n提示\n## 明天\n- [ ] 下一步\n");return vault;
    }
}